# Правильно:
def save(key, value, storage=None):
    if storage is None:
        storage = {}
    storage[key] = value
    return storage

def logged(func):
    def wrapper():
        print(f'-> вызываю {func.__name__}')
        result = func()
        print(f'<- {func.__name__} отработала')
        return result
    return wrapper


@logged
def greet():
    print('Привет!')


greet()      # тот же результат

