def positive_only(func):
    def wrapper(number):
        if number < 0:
            raise ValueError('Отрицательные числа не принимаются')
        return func(number)
    return wrapper


@positive_only
def square_root(number):
    return number ** 0.5


print(square_root(16))  # 4.0
print(square_root(-4))  # ValueError: Отрицательные числа не принимаются

